{"path":"/workspace/src/store.js","content":"import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export function defaultBooksFile() {
  return fileURLToPath(new URL("../data/books.json", import.meta.url));
}

export class BookStore {
  constructor(filePath = defaultBooksFile()) {
    this.filePath = filePath;
    this.queue = Promise.resolve();
  }

  run(task) {
    const run = this.queue.then(task, task);
    this.queue = run.then(
      () => {},
      () => {},
    );
    return run;
  }

  async load() {
    try {
      const text = await readFile(this.filePath, "utf8");
      if (text.trim() === "") return [];
      const data = JSON.parse(text);
      if (!Array.isArray(data)) {
        throw new Error(`Expected a JSON array in ${this.filePath}`);
      }
      return data;
    } catch (error) {
      if (error && error.code === "ENOENT") return [];
      throw error;
    }
  }

  async save(books) {
    await mkdir(dirname(this.filePath), { recursive: true });
    const temporary = join(
      dirname(this.filePath),
      `.${process.pid}-${Date.now()}.books.tmp`,
    );
    await writeFile(temporary, `${JSON.stringify(books, null, 2)}\n`, "utf8");
    await rename(temporary, this.filePath);
  }

  list() {
    return this.run(() => this.load());
  }

  get(id) {
    return this.run(async () => {
      const books = await this.load();
      return books.find((book) => book.id === id) ?? null;
    });
  }

  add({ title, author, notes }) {
    return this.run(async () => {
      const books = await this.load();
      const book = {
        id: randomUUID(),
        title: title.trim(),
        author: author.trim(),
        notes: notes.trim(),
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await this.save(books);
      return book;
    });
  }

  finish(id) {
    return this.run(async () => {
      const books = await this.load();
      const book = books.find((item) => item.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await this.save(books);
      }
      return book;
    });
  }
}
"}

{"path":"/workspace/src/render.js","content":"export function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function page({ title, body }) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4efe6;
      --ink: #1f1a17;
      --muted: #6b625b;
      --line: #e4d9cc;
      --card: #fffdf9;
      --accent: #8c3a2f;
      --accent-ink: #fffaf7;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      background: var(--bg);
      color: var(--ink);
      font: 17px/1.5 Georgia, "Iowan Old Style", Palatino, serif;
    }
    a { color: var(--accent); }
    header { border-bottom: 1px solid var(--line); background: var(--card); }
    header .inner, main {
      width: min(40rem, calc(100% - 2rem));
      margin: 0 auto;
    }
    header .inner { padding: 1rem 0; }
    header a.brand {
      color: inherit;
      text-decoration: none;
      font-size: 1.25rem;
    }
    main { padding: 1.75rem 0 4rem; }
    h1, h2 { font-weight: 500; letter-spacing: -0.02em; }
    h1 { font-size: 2rem; margin: 0 0 0.35rem; }
    h2 { font-size: 1.15rem; margin: 2rem 0 0.5rem; }
    .by, .status, .empty, .share { color: var(--muted); }
    .by, .status, .empty { margin: 0.15rem 0 0; }
    .shelf { list-style: none; padding: 0; margin: 0; }
    .shelf li {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: center;
      padding: 0.85rem 0;
      border-bottom: 1px solid var(--line);
    }
    .shelf a { color: inherit; text-decoration: none; }
    .shelf a:hover { color: var(--accent); }
    form.card, article.book {
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 1rem 1.1rem;
    }
    label { display: grid; gap: 0.3rem; margin: 0 0 0.8rem; }
    input, textarea {
      font: inherit;
      color: inherit;
      background: #fff;
