      font: inherit;
      background: var(--accent);
      color: var(--accent-ink);
      border: 0;
      border-radius: 6px;
      padding: 0.45rem 0.8rem;
      cursor: pointer;
    }
    button.secondary {
      background: transparent;
      color: var(--ink);
      border: 1px solid var(--line);
    }
