    .back { display: inline-block; margin-bottom: 1rem; }
    .actions { margin-top: 1.25rem; }
  </style>
</head>
<body>
  <header>
    <div class="inner"><a class="brand" href="/">Books</a></div>
  </header>
  <main>
    ${body}
  </main>
</body>
