`;
}

function bookItem(book) {
  const title = escapeHtml(book.title);
  const author = escapeHtml(book.author);
  const id = encodeURIComponent(book.id);
  const finish =
    book.status === "reading"
      ? `<form method="post" action="/books/${id}/finish">
          <input type="hidden" name="next" value="/">
          <button class="secondary" type="submit" aria-label="Mark ${title} finished">Mark finished</button>
        </form>`
      : "";
  return `<li>
    <div>
      <a href="/books/${id}">${title}</a>
      <p class="by">${author}</p>
    </div>
    ${finish}
  </li>`;
}

function shelf(books) {
  if (books.length === 0) return `<p class="empty">Nothing here yet.</p>`;
  return `<ul class="shelf">${books.map(bookItem).join("")}</ul>`;
}

export function renderHome(books, { error = "", values = {} } = {}) {
  const reading = books.filter((book) => book.status !== "finished");
  const finished = books.filter((book) => book.status === "finished");
  const title = values.title ?? "";
  const author = values.author ?? "";
  const notes = values.notes ?? "";
  const errorHtml = error
    ? `<p class="error" role="alert">${escapeHtml(error)}</p>`
    : "";

  return page({
    title: "Books",
    body: `
      <h1>Books</h1>
      <section id="reading" aria-labelledby="reading-heading">
        <h2 id="reading-heading">Currently reading</h2>
        ${shelf(reading)}
      </section>
      <section id="finished" aria-labelledby="finished-heading">
        <h2 id="finished-heading">Finished</h2>
        ${shelf(finished)}
      </section>
      <section id="add-book" aria-labelledby="add-heading">
        <h2 id="add-heading">Add a book</h2>
        <form class="card" method="post" action="/books">
          ${errorHtml}
          <label>Title
            <input name="title" required maxlength="200" value="${escapeHtml(title)}">
          </label>
          <label>Author
            <input name="author" required maxlength="200" value="${escapeHtml(author)}">
          </label>
          <label>Notes
            <textarea name="notes" maxlength="5000">${escapeHtml(notes)}</textarea>
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>
    `,
  });
}

export function renderBook(book, shareUrl) {
  const id = encodeURIComponent(book.id);
  const status =
    book.status === "finished" ? "Finished" : "Currently reading";
  const notes = book.notes
    ? `<p class="notes">${escapeHtml(book.notes)}</p>`
    : `<p class="notes empty">No notes yet.</p>`;
  const finish =
    book.status === "reading"
      ? `<form class="actions" method="post" action="/books/${id}/finish">
          <input type="hidden" name="next" value="/books/${id}">
          <button type="submit">Mark finished</button>
        </form>`
      : "";

  return page({
    title: book.title,
    body: `
      <a class="back" href="/">All books</a>
      <article class="book" id="book">
        <h1>${escapeHtml(book.title)}</h1>
        <p class="by">${escapeHtml(book.author)}</p>
        <p class="status">${status}</p>
        <h2>Notes</h2>
        ${notes}
        <p class="share">Send this link: <a href="${escapeHtml(shareUrl)}">${escapeHtml(shareUrl)}</a></p>
        ${finish}
      </article>
    `,
  });
}

export function renderMessage({ title, message, status = 404 }) {
  return {
    status,
    html: page({
      title,
      body: `
        <h1>${escapeHtml(title)}</h1>
        <p>${escapeHtml(message)}</p>
        <p><a href="/">All books</a></p>
      `,
    }),
  };
}
