{"path":"/workspace/src/app.js","content":"import { createServer } from "node:http";
import { renderBook, renderHome, renderMessage } from "./render.js";

const MAX_BODY = 64 * 1024;

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error("Body too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

function sendHtml(res, status, body) {
  res.writeHead(status, {
    "Content-Type": "text/html; charset=utf-8",
    "Cache-Control": "no-store",
  });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location, "Cache-Control": "no-store" });
  res.end();
}

function decodePathId(raw) {
  try {
    return decodeURIComponent(raw);
  } catch {
    return null;
  }
}

function safeNext(value, fallback) {
  if (typeof value !== "string") return fallback;
  if (!value.startsWith("/") || value.startsWith("//")) return fallback;
  if (/[\r\n\0\\]/.test(value)) return fallback;
  return value;
}

function shareUrl(req, id) {
  const host = req.headers.host || "localhost";
  const forwarded = req.headers["x-forwarded-proto"];
  const proto = forwarded === "https" ? "https" : "http";
  return `${proto}://${host}/books/${encodeURIComponent(id)}`;
}

export function createApp(store) {
  return async function handle(req, res) {
    const url = new URL(req.url || "/", "http://localhost");
    const path = url.pathname;
    const method = req.method || "GET";

    if (method === "GET" && path === "/") {
      const books = await store.list();
      sendHtml(res, 200, renderHome(books));
      return;
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (method === "GET" && bookMatch) {
      const id = decodePathId(bookMatch[1]);
      const book = id ? await store.get(id) : null;
      if (!book) {
        const missing = renderMessage({
          title: "Book not found",
          message: "That book is not on the shelf.",
        });
        sendHtml(res, missing.status, missing.html);
        return;
      }
      sendHtml(res, 200, renderBook(book, shareUrl(req, book.id)));
      return;
    }

    if (method === "POST" && path === "/books") {
      const form = new URLSearchParams(await readBody(req));
      const title = form.get("title") ?? "";
      const author = form.get("author") ?? "";
      const notes = form.get("notes") ?? "";
      if (!title.trim() || !author.trim()) {
        const books = await store.list();
        sendHtml(
          res,
          400,
          renderHome(books, {
            error: "Title and author are required.",
            values: { title, author, notes },
          }),
        );
        return;
      }
      const book = await store.add({ title, author, notes });
      redirect(res, `/books/${encodeURIComponent(book.id)}`);
      return;
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (method === "POST" && finishMatch) {
      const id = decodePathId(finishMatch[1]);
      const book = id ? await store.finish(id) : null;
      if (!book) {
        const missing = renderMessage({
          title: "Book not found",
          message: "That book is not on the shelf.",
        });
        sendHtml(res, missing.status, missing.html);
        return;
      }
      const form = new URLSearchParams(await readBody(req));
      redirect(res, safeNext(form.get("next"), `/books/${encodeURIComponent(book.id)}`));
      return;
    }

    if (method !== "GET" && method !== "HEAD") {
      const methodError = renderMessage({
        title: "Method not allowed",
        message: "That action is not available.",
        status: 405,
      });
      sendHtml(res, methodError.status, methodError.html);
      return;
    }

    const notFound = renderMessage({
      title: "Page not found",
      message: "That page is not here.",
    });
    sendHtml(res, notFound.status, notFound.html);
  };
}

export function createServerApp(store) {
  const handle = createApp(store);
  return createServer((req, res) => {
    Promise.resolve(handle(req, res)).catch((error) => {
      console.error(error);
      if (res.headersSent) {
        res.end();
        return;
      }
      const status = error && error.status === 413 ? 413 : 500;
      const message =
        status === 413 ? "That was too much text." : "Something went wrong.";
      const page = renderMessage({
        title: "Something went wrong",
        message,
        status,
      });
      sendHtml(res, page.status, page.html);
    });
  });
}

export function startServer({ store, port = 3000, host = "127.0.0.1" }) {
  const server = createServerApp(store);
  return new Promise((resolve, reject) => {
    const onError = (error) => reject(error);
    server.once("error", onError);
    server.listen(port, host, () => {
      server.off("error", onError);
      resolve(server);
    });
  });
}
"}

