{"path":"/workspace/test/books.test.js","content":"import { createServer } from "node:http";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { createApp } from "../src/app.js";
import { BookStore } from "../src/store.js";

const cleanups = [];

afterEach(async () => {
  while (cleanups.length > 0) {
    await cleanups.pop()();
  }
});

async function launch(store) {
  const server = createServer((req, res) => {
    Promise.resolve(createApp(store)(req, res)).catch((error) => {
      res.writeHead(500, { "Content-Type": "text/plain; charset=utf-8" });
      res.end(error.message);
    });
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address();
  cleanups.push(
    () =>
      new Promise((resolve, reject) => {
        server.close((error) => (error ? reject(error) : resolve()));
      }),
  );
  return `http://127.0.0.1:${port}`;
}

async function tempStore() {
  const dir = await mkdtemp(join(tmpdir(), "books-"));
  cleanups.push(() => rm(dir, { recursive: true, force: true }));
  return new BookStore(join(dir, "books.json"));
}

function section(html, id) {
  const start = html.indexOf(`id="${id}"`);
  expect(start).toBeGreaterThan(-1);
  const rest = html.slice(start);
  const next = rest.indexOf("<section", 1);
  return next === -1 ? rest : rest.slice(0, next);
}

async function postForm(base, path, fields) {
  return fetch(`${base}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams(fields),
    redirect: "manual",
  });
}

describe("book shelf", () => {
  it("shows currently reading and finished books, and keeps them in the JSON file", async () => {
    const store = await tempStore();
    const reading = await store.add({
      title: "The Left Hand of Darkness",
      author: "Ursula K. Le Guin",
      notes: "Winter",
    });
    const done = await store.add({
      title: "Piranesi",
      author: "Susanna Clarke",
      notes: "House",
    });
    await store.finish(done.id);

    const reloaded = new BookStore(store.filePath);
    const saved = await reloaded.list();
    expect(saved).toEqual([
      expect.objectContaining({
        id: reading.id,
        title: "The Left Hand of Darkness",
        status: "reading",
        finishedAt: null,
      }),
      expect.objectContaining({
        id: done.id,
        title: "Piranesi",
        status: "finished",
      }),
    ]);
    expect(saved[1].finishedAt).toEqual(expect.any(String));

    const onDisk = JSON.parse(await readFile(store.filePath, "utf8"));
    expect(onDisk.map((book) => book.title)).toEqual([
      "The Left Hand of Darkness",
      "Piranesi",
    ]);

    const base = await launch(reloaded);
    const home = await fetch(`${base}/`);
    expect(home.status).toBe(200);
    const html = await home.text();
    const readingHtml = section(html, "reading");
    const finishedHtml = section(html, "finished");
    expect(readingHtml).toContain("Currently reading");
    expect(readingHtml).toContain("The Left Hand of Darkness");
    expect(readingHtml).toContain("Ursula K. Le Guin");
    expect(readingHtml).not.toContain("Piranesi");
    expect(finishedHtml).toContain("Finished");
    expect(finishedHtml).toContain("Piranesi");
    expect(finishedHtml).not.toContain("The Left Hand of Darkness");
    expect(html).toContain('action="/books"');
  });

  it("adds a book from the form and serves a shareable book page", async () => {
    const store = await tempStore();
    const base = await launch(store);
    const created = await postForm(base, "/books", {
      title: " Kindred ",
      author: " Octavia Butler ",
      notes: "Notes about <time> travel",
    });
    expect(created.status).toBe(303);
    const location = created.headers.get("location");
    expect(location).toMatch(/^\/books\/[^/]+$/);

    const page = await fetch(`${base}${location}`);
    expect(page.status).toBe(200);
    const html = await page.text();
    expect(html).toContain("<h1>Kindred</h1>");
    expect(html).toContain("Octavia Butler");
    expect(html).toContain("Notes about &lt;time&gt; travel");
    expect(html).not.toContain("<time>");
    expect(html).toContain(`Send this link: <a href="http://127.0.0.1`);
    expect(html).toContain(location);

    const again = new BookStore(store.filePath);
    const [book] = await again.list();
    expect(book).toMatchObject({
      title: "Kindred",
      author: "Octavia Butler",
      notes: "Notes about <time> travel",
      status: "reading",
    });
    expect(`${base}/books/${book.id}`).toBe(`${base}${location}`);
  });

  it("marks a book finished from the shelf and from its page", async () => {
    const store = await tempStore();
    const book = await store.add({
      title: "Circe",
      author: "Madeline Miller",
      notes: "Island",
    });
    const base = await launch(store);

    const fromShelf = await postForm(base, `/books/${book.id}/finish`, {
      next: "/",
    });
    expect(fromShelf.status).toBe(303);
    expect(fromShelf.headers.get("location")).toBe("/");

    let home = await (await fetch(`${base}/`)).text();
    expect(section(home, "reading")).not.toContain("Circe");
    expect(section(home, "finished")).toContain("Circe");

    const second = await store.add({
      title: "Hamnet",
      author: "Maggie O'Farrell",
      notes: "",
    });
    const fromPage = await postForm(base, `/books/${second.id}/finish`, {
      next: `/books/${second.id}`,
    });
    expect(fromPage.headers.get("location")).toBe(`/books/${second.id}`);
    const detail = await (await fetch(`${base}/books/${second.id}`)).text();
    expect(detail).toContain("Hamnet");
    expect(detail).toContain("Maggie O&#39;Farrell");
    expect(detail).toContain("Finished");
    expect(detail).toContain("No notes yet.");
    expect(detail).not.toContain("Mark finished");
  });

  it("rejects a book with no title and ignores unknown pages", async () => {
    const store = await tempStore();
    const base = await launch(store);
    const rejected = await postForm(base, "/books", {
      title: "   ",
      author: "Someone",
      notes: "kept",
    });
    expect(rejected.status).toBe(400);
    const html = await rejected.text();
    expect(html).toContain("Title and author are required.");
    expect(html).toContain("kept");
    expect(await store.list()).toEqual([]);

    const missing = await fetch(`${base}/books/missing-book`);
    expect(missing.status).toBe(404);
    expect(await missing.text()).toContain("Book not found");
  });
});
"}

