      `.${process.pid}-${Date.now()}.books.tmp`,
    );
    await writeFile(temporary, `${JSON.stringify(books, null, 2)}\n`, "utf8");
    await rename(temporary, this.filePath);
  }

  list() {
    return this.run(() => this.load());
  }

  get(id) {
    return this.run(async () => {
      const books = await this.load();
      return books.find((book) => book.id === id) ?? null;
    });
  }

  add({ title, author, notes }) {
    return this.run(async () => {
      const books = await this.load();
      const book = {
        id: randomUUID(),
        title: title.trim(),
        author: author.trim(),
        notes: notes.trim(),
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await this.save(books);
      return book;
    });
  }

  finish(id) {
    return this.run(async () => {
      const books = await this.load();
      const book = books.find((item) => item.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await this.save(books);
      }
      return book;
    });
  }
}

import { BookStore, defaultBooksFile } from "./store.js";
import { startServer } from "./app.js";

const filePath = process.env.BOOKS_FILE || defaultBooksFile();
const port = Number(process.env.PORT) || 3000;
const host = process.env.HOST || "127.0.0.1";

const store = new BookStore(filePath);
const server = await startServer({ store, port, host });
const address = server.address();
const shownHost = host === "0.0.0.0" || host === "::" ? "localhost" : host;
console.log(`Books is running at http://${shownHost}:${address.port}`);
console.log(`Saving books to ${filePath}`);

